import React from 'react';
import { useNavigate } from 'react-router-dom';
import './Admin.css';
import PageTitle from '../PageTitle';

function Admin() {
    const navigate = useNavigate(); // useNavigate hook'unu kullanarak yönlendirme işlemi yapacağız

    const handleLogout = () => {
        // Burada çıkış işlemini yapabilirsiniz, örneğin kullanıcıyı oturumdan çıkarmak için kod ekleyebilirsiniz
        navigate('/'); // Çıkış yaptıktan sonra ana sayfaya yönlendirir
    };

    return (
        <>
            <PageTitle title='Kontrol Paneli'/>
            <div className="admin-panel">
                {/* Sidebar */}
                <aside className="sidebar">
                    <h2>BeeonHive</h2>
                    <nav>
                        <ul>
                            <li>Admin Paneli</li>
                            <li>Ürünlere Göz At</li>
                            <li>İletişim</li>
                            <li onClick={handleLogout}>Çıkış Yap</li> {/* Çıkış yap butonuna tıklanınca yönlendir */}
                        </ul>
                    </nav>
                </aside>

                {/* Main Content */}
                <main className="main-content">
                    <div className="stats-container">
                        <div className="stat-box">
                            <h3>Toplam Ürün</h3>
                            <p>0</p>
                        </div>
                        <div className="stat-box">
                            <h3>Toplam İleti</h3>
                            <p>0</p>
                        </div>
                        <div className="stat-box">
                            <h3>Toplam Kullanıcı</h3>
                            <p>0</p>
                        </div>
                    </div>
                </main>
            </div>
        </>
    );
}

export default Admin;
